cont=[0]+list(range(10,20))
lo=np.array([-4.2]+[0.]*19);width=np.array([8.2]+[1.]*9+[10.]*10)
ks=[0.,.25,.5,.75]
desc=[(-1,0,-1,0)]
for i in range(20):
 for k in range(4 if i in cont else 1):desc.append((i,k,-1,0))
main=len(desc)
for i in range(20):
 for j in range(i+1,20):
  for k in range(4 if i in cont else 1):
   for l in range(4 if j in cont else 1):desc.append((i,k,j,l))
def design(X,ds=desc):
 T=(X-lo)/width
 B=[np.maximum(T[:,i:i+1]-np.array(ks[:(4 if i in cont else 1)]),0) for i in range(20)]
 A=np.empty((len(X),len(ds)))
 for z,(i,k,j,l) in enumerate(ds):
  if i<0:A[:,z]=1
  elif j<0:A[:,z]=B[i][:,k]
  else:A[:,z]=B[i][:,k]*B[j][:,l]
 return A
def export(ds,beta):
 inter=float(beta[0]);terms={};interactions=[]
 def addterm(i,k,b):terms[(i,k)]=terms.get((i,k),0)+float(b)
 for d,b in zip(ds[1:],beta[1:]):
  i,k,j,l=d
  if j<0:
   addterm(i,k,b/width[i])
   if k==0:inter-=float(b)*lo[i]/width[i]
  else:
   c=float(b)/(width[i]*width[j])
   if k==0 and l==0:
    interactions.append({'inputs':[INPUTS[i],INPUTS[j]],'coef':round(c,7)})
    addterm(j,0,-lo[i]*c)
    addterm(i,0,-lo[j]*c)
    inter+=lo[i]*lo[j]*c
   else:interactions.append({'inputs':[INPUTS[i],INPUTS[j]],'knots':[round(float(lo[i]+width[i]*ks[k]),4),round(float(lo[j]+width[j]*ks[l]),4)],'coef':round(c,7)})
 ts=[]
 for (i,k),b in sorted(terms.items()):
  if k==0:ts.append({'input':INPUTS[i],'type':'linear','coef':round(b,7)})
  else:ts.append({'input':INPUTS[i],'type':'hinge','knot':round(float(lo[i]+width[i]*ks[k]),4),'coef':round(b,7)})
 return {'intercept':round(float(inter),7),'terms':ts,'interactions':interactions}

